// Block (composition) — a full-width site footer with navigation and legal copy.
// Contract: docs/rules/block-contract.md. Arranges only (Grid/Stack for layout);
// composes Link and Separator. Owns no Component look; mints no tokens.
import type { Ref } from "react";
import { Grid } from "../layouts/Grid";
import { Link } from "../components/Link";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import "./Footer.css";

export interface FooterProps {
  /** Groups of footer links. */
  sections?: { heading: string; links: { label: string; href: string }[] }[];
  /** Legal or copyright text shown below the divider. */
  copyright?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function Footer({
  sections = [],
  copyright = `© ${new Date().getFullYear()} Sando UI. All rights reserved.`,
  className,
  ref,
}: FooterProps) {
  return (
    <Stack
      as="footer"
      ref={ref}
      gap="large"
      className={className ? `sd-footer ${className}` : "sd-footer"}
    >
      <Grid columns={{ small: 2, medium: 4 }} gap="large">
        {sections.map((section) => (
          <Stack key={section.heading} gap="x-small" className="sd-footer__column">
            {/* CONTRASTIVE: one rung below the links it heads, as a collection's section-header. */}
            <h2 className="sd-footer__heading sd-type-label-small">{section.heading}</h2>
            {section.links.map((link, index) => (
              <Link key={`${link.label}-${index}`} href={link.href} variant="quiet" className="sd-type-label-medium">
                {link.label}
              </Link>
            ))}
          </Stack>
        ))}
      </Grid>
      <Separator />
      <p className="sd-footer__copyright sd-type-caption-medium">{copyright}</p>
    </Stack>
  );
}

/* Footer.css — .sd-footer (Block)
   Arrangement only: fills its available width and removes native text margins.
   Columns and grouping are owned by Grid/Stack. No width cap or new tokens. */
/* A page-closing band takes `2x-large` block padding (token-contract.md § By relationship, insets),
   so the copyright line keeps off the bottom edge without a host's margin. */
.sd-footer {
  width: 100%;
  padding-block: var(--sd-space-2x-large);
}

.sd-footer__heading,
.sd-footer__copyright {
  margin: 0;
}
